package com.cryptostrategy.platform.backtesting.internal;
import static org.junit.jupiter.api.Assertions.*;import com.cryptostrategy.platform.backtesting.api.error.BacktestException;import com.cryptostrategy.platform.marketdata.api.model.CandleBatch;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;
class DatasetBatchCursorContractTest{@Test void startsAtZeroAndTraversesEveryCandleOnceAcrossBatches(){BacktestTestFixture f=new BacktestTestFixture();AtomicInteger seen=new AtomicInteger();new DatasetBatchCursor(f.command(1),f.reader()).forEach((c,last)->seen.incrementAndGet());assertEquals(3,seen.get());}@Test void rejectsNonContiguousOrOversizedProgress(){BacktestTestFixture f=new BacktestTestFixture();assertThrows(BacktestException.class,()->new DatasetBatchCursor(f.command(1),(id,from,size)->new CandleBatch(id,from,f.members,3,false)).forEach((c,last)->{}));}}
